	private static Map<String, ExpectedPage> expectedPages() {
		List<Quad> quads = tutorialQuads();
		List<Long> predicates = quads.stream()
				.map(Quad::predicate)
				.distinct()
				.sorted(Long::compareUnsigned)
				.toList();
		Map<Long, Integer> predicateOrdinals = new HashMap<>();
		for (int ordinal = 0; ordinal < predicates.size(); ordinal++) {
			predicateOrdinals.put(predicates.get(ordinal), ordinal);
		}

		Comparator<Long> unsigned = Long::compareUnsigned;
		Map<Partition, TreeMap<Long, TreeMap<Long, TreeSet<Long>>>> partitions = new TreeMap<>(
				Comparator.comparingInt(Partition::predicateOrdinal).thenComparingInt(Partition::plane));
		for (Quad quad : quads) {
			int predicateOrdinal = predicateOrdinals.get(quad.predicate);
			int outgoingPlane = quad.explicit ? 0 : 2;
			int incomingPlane = quad.explicit ? 1 : 3;
			add(partitions, new Partition(predicateOrdinal, outgoingPlane), quad.subject, quad.object, quad.context,
					unsigned);
			add(partitions, new Partition(predicateOrdinal, incomingPlane), quad.object, quad.subject, quad.context,
					unsigned);
		}

		Map<String, ExpectedPage> pages = new LinkedHashMap<>();
		int pageId = 0;
		for (Map.Entry<Partition, TreeMap<Long, TreeMap<Long, TreeSet<Long>>>> entry : partitions.entrySet()) {
			CsfPageData data = pageData(entry.getValue());
			CompactCsfPageEncoder.PageImage image = Objects.requireNonNull(
					new CompactCsfPageEncoder().tryEncode(data, false, pageId),
					"tutorial partition must fit one page");
			pages.put(entry.getKey().key(), new ExpectedPage(data, image));
			pageId++;
		}
		assertThat(pages.keySet()).containsExactly("0:0", "0:1", "0:2", "0:3", "1:0", "1:1");
		return pages;
	}

	private static void add(Map<Partition, TreeMap<Long, TreeMap<Long, TreeSet<Long>>>> partitions,
			Partition partition, long row, long neighbor, long context, Comparator<Long> unsigned) {
		partitions.computeIfAbsent(partition, ignored -> new TreeMap<>(unsigned))
				.computeIfAbsent(row, ignored -> new TreeMap<>(unsigned))
				.computeIfAbsent(neighbor, ignored -> new TreeSet<>(unsigned))
				.add(context);
	}

	private static CsfPageData pageData(TreeMap<Long, TreeMap<Long, TreeSet<Long>>> rows) {
		CsfPageData data = new CsfPageData();
		for (Map.Entry<Long, TreeMap<Long, TreeSet<Long>>> row : rows.entrySet()) {
			long[] neighbors = new long[row.getValue().size()];
			int[] contextStarts = new int[neighbors.length];
			int[] contextCounts = new int[neighbors.length];
			List<Long> contexts = new ArrayList<>();
			int fiber = 0;
			for (Map.Entry<Long, TreeSet<Long>> neighbor : row.getValue().entrySet()) {
				neighbors[fiber] = neighbor.getKey();
				contextStarts[fiber] = contexts.size();
				contextCounts[fiber] = neighbor.getValue().size();
				contexts.addAll(neighbor.getValue());
				fiber++;
			}
			long[] rawContexts = contexts.stream().mapToLong(Long::longValue).toArray();
			data.appendRow(row.getKey(), neighbors, contextStarts, contextCounts, rawContexts, neighbors.length,
					rawContexts.length);
		}
		return data;
	}

	private static void assertValidPage(String key, ExpectedPage fixture) {
		byte[] bytes = fixture.image.bytes();
		assertThat(LeBytes.getInt(bytes, CompactCsfPageFormat.MAGIC_AT)).isEqualTo(CompactCsfPageFormat.MAGIC);
		assertThat(LeBytes.getUnsignedShort(bytes, CompactCsfPageFormat.VERSION_AT))
				.isEqualTo(CompactCsfPageFormat.VERSION);
		assertThat(LeBytes.getInt(bytes, CompactCsfPageFormat.FORMAT_HASH_AT))
				.isEqualTo(CompactCsfPageFormat.FORMAT_HASH);
		assertThat(LeBytes.getInt(bytes, CompactCsfPageFormat.USED_AT)).isEqualTo(bytes.length);
		assertThat(LeBytes.getInt(bytes, CompactCsfPageFormat.CAPACITY_AT)).isEqualTo(fixture.image.capacity());
		assertThat(fixture.image.capacity() % NativeSlabAllocator.PAGE_GRANULARITY).isZero();

		int expectedFlags = key.equals("0:0") || key.equals("0:1") ? 0
				: CompactCsfPageFormat.FLAG_ROW_NEIGHBOR_ONE
						| CompactCsfPageFormat.FLAG_ROW_QUAD_EQUALS_NEIGHBOR
						| CompactCsfPageFormat.FLAG_CONTEXT_COUNT_ONE
						| CompactCsfPageFormat.FLAG_COMMON_CONTEXT;
		assertThat(LeBytes.getUnsignedShort(bytes, CompactCsfPageFormat.FLAGS_AT)).isEqualTo(expectedFlags);
		assertSectionBoundaries(bytes);

		long address = UnsafeAccess.allocateZeroed(fixture.image.capacity() + PackedLongVector.READ_TAIL_PADDING);
		try {
			UnsafeAccess.copyFromArray(bytes, 0, address, bytes.length);
			CompactCsfPageReader.validatePage(address);
			CompactCsfPageReader reader = new CompactCsfPageReader(address);
			assertThat(reader.rowCount()).isEqualTo(fixture.data.rowCount);
			for (int row = 0; row < fixture.data.rowCount; row++) {
				assertThat(reader.rowAt(row)).isEqualTo(fixture.data.rows[row]);
				assertThat(reader.rowNeighborCount(row)).isEqualTo(fixture.data.rowFiberCounts[row]);
				int firstFiber = fixture.data.rowFiberStarts[row];
				for (int localFiber = 0; localFiber < fixture.data.rowFiberCounts[row]; localFiber++) {
					int fiber = firstFiber + localFiber;
					assertThat(reader.neighborAtFiber(row, localFiber)).isEqualTo(fixture.data.neighbors[fiber]);
					assertThat(reader.fiberContextCount(fiber)).isEqualTo(fixture.data.fiberContextCounts[fiber]);
					for (int localContext = 0; localContext < fixture.data.fiberContextCounts[fiber]; localContext++) {
						assertThat(reader.contextAt(fiber, localContext))
								.isEqualTo(
										fixture.data.contexts[fixture.data.fiberContextStarts[fiber] + localContext]);
					}
				}
			}
		} finally {
			UnsafeAccess.free(address);
		}
	}

	private static void assertSectionBoundaries(byte[] page) {
		int[] offsetFields = { CompactCsfPageFormat.ROW_IDS_OFFSET_AT,
				CompactCsfPageFormat.ROW_FIBER_STARTS_OFFSET_AT,
				CompactCsfPageFormat.ROW_QUAD_COUNTS_OFFSET_AT,
				CompactCsfPageFormat.FIRST_NEIGHBORS_OFFSET_AT,
				CompactCsfPageFormat.NEIGHBOR_TAILS_OFFSET_AT,
				CompactCsfPageFormat.CONTEXT_COUNTS_OFFSET_AT,
				CompactCsfPageFormat.FIRST_CONTEXTS_OFFSET_AT,
				CompactCsfPageFormat.CONTEXT_TAILS_OFFSET_AT };
		int previousEnd = CompactCsfPageFormat.HEADER_BYTES;
		for (int offsetField : offsetFields) {
			int offset = LeBytes.getInt(page, offsetField);
			int length = LeBytes.getInt(page, offsetField + Integer.BYTES);
			if (offset == 0) {
				assertThat(length).isZero();
				continue;
			}
			assertThat(offset).isGreaterThanOrEqualTo(previousEnd);
			assertThat(offset % Long.BYTES).isZero();
			assertThat(length).isPositive();
			assertThat(offset + length).isLessThanOrEqualTo(page.length);
			previousEnd = offset + length;
		}
		assertThat(LeBytes.getInt(page, CompactCsfPageFormat.ACCELERATOR_DESCRIPTOR_AT)).isZero();
		assertThat(LeBytes.getInt(page, CompactCsfPageFormat.ACCELERATOR_OFFSET_AT)).isZero();
		assertThat(LeBytes.getInt(page, CompactCsfPageFormat.ACCELERATOR_LENGTH_AT)).isZero();
		assertThat(LeBytes.align8(previousEnd)).isEqualTo(page.length);
	}

