	private static Path repositoryRoot() {
		String multiModuleRoot = System.getProperty("maven.multiModuleProjectDirectory");
		if (multiModuleRoot != null) {
			Path candidate = Path.of(multiModuleRoot).toAbsolutePath().normalize();
			if (Files.isDirectory(candidate.resolve("site/static"))) {
				return candidate;
			}
		}
		Path candidate = Path.of("").toAbsolutePath().normalize();
		while (candidate != null) {
			if (Files.isDirectory(candidate.resolve("site/static"))
					&& Files.isRegularFile(candidate.resolve("pom.xml"))) {
				return candidate;
			}
			candidate = candidate.getParent();
		}
		throw new IllegalStateException("could not locate the RDF4J repository root");
	}

	private static long id(int type, long payload) {
		return payload << 7 | (long) type << 1;
	}

